        if ln.t == "+":
            bg, sign, sign_c, num_c, hl_c = add_bg, "+", t.ok, t.text_3, add_hl
        elif ln.t == "-":
            bg, sign, sign_c, num_c, hl_c = del_bg, "−", t.err, t.text_3, del_hl
