                K["panel"].keys,
            ),
            Cmd("view", "Cycle view: Normal → Thinking → Verbose", "eye", "Actions", s.cycle_view, "", K["view"].keys),
            Cmd(
                "overview",
                "Control room",
                "layout-grid",
                "Actions",
                lambda: s.show_page("overview"),
                "Every session at a glance; answer prompts in place",
                K["overview"].keys,
            ),
            Cmd(
                "skills",
                "Skills…",
                "scroll-text",
                "Actions",
                lambda: s.set_dialog("settings", "skills"),
