        )
        if self._focused:
            line = QColor(t.text_3)
        else:
            line = theme.blend(t.hair_3 if self.underMouse() else t.hair_2, t.canvas)
        p = QPainter(self)
        paint_box(p, QRectF(self.rect()), bg, line, self._radius)


