# ---------------------------------------------------------------- Seg, Switch, RadioRow


class Seg(QWidget):
    """Segmented control (``Seg`` in bits.tsx / ``.seg``): one of a few short choices. The chosen
    segment carries the thumb (fill-3 on dark, raised with a shadow on light)."""

    changed = Signal(str)

    def __init__(
        self,
        options: Sequence[Tuple[str, str]],
        value: str = "",
        small: bool = False,
        name: str = "",
        parent: Optional[QWidget] = None,
    ) -> None:
        super().__init__(parent)
        self.setAccessibleName(name)
        self.setSizePolicy(QSizePolicy.Policy.Fixed, QSizePolicy.Policy.Fixed)
        lay = QHBoxLayout(self)
        lay.setContentsMargins(2, 2, 2, 2)
        lay.setSpacing(0)
        self.group = QButtonGroup(self)
        self.group.setExclusive(True)
        self.buttons: Dict[str, QPushButton] = {}
        h = 22 if small else 24
        pad = 7 if small else 10
        for v, text in options:
            b = Btn(text)
            b.override.update(h=h - 2, px=pad - 1, fs=theme.FS_SMALL, fw=500, r=6)
            b.set_look(
                "text_3",
                "text",
                on_fg="text",
                on_bg=lambda t: theme.blend(t.fill_3, sheet_bg(t).name()) if t.dark else theme.qcolor(t.raised),
                on_line=lambda t: None if t.dark else theme.blend(t.hair, t.raised),
            )
            b.setCheckable(True)
            b.setAutoDefault(False)
            b.setAccessibleName(text)
            b.setCursor(Qt.CursorShape.PointingHandCursor)
            b.setFocusPolicy(Qt.FocusPolicy.TabFocus)
            b.clicked.connect(lambda _c=False, val=v: self._pick(val))
            lay.addWidget(b)
            self.group.addButton(b)
            self.buttons[v] = b
        bind(theme.theme.changed, self, lambda _t: self.update())
        self.set_value(value)

    def paintEvent(self, _e) -> None:
        t = theme.tokens()
        bg = _field_bg(t)
        p = QPainter(self)
        paint_box(p, QRectF(self.rect()), bg, theme.blend(t.hair, bg.name()), 8)

    @property
    def value(self) -> str:
        return self._value

    def set_value(self, v: str) -> None:
        self._value = v
        b = self.buttons.get(v)
        if b is not None:
            b.setChecked(True)

    def _pick(self, v: str) -> None:
        if v == self._value:
            self.buttons[v].setChecked(True)
            return
        self._value = v
        self.changed.emit(v)


class Switch(_Switch):
