        self.open_btn.setIconSize(QSize(11, 11))
        self.open_btn.clicked.connect(lambda _c=False: (self._on_read(), store.open_job(str(it.get("jobId")))))
        foot.addWidget(self.open_btn)
        self.x_btn = IconButton("x", "Dismiss", 13)
