                if not self.filter
                or i.get("scheduleId") == self.filter
                or (self.filter == "dispatch" and i.get("kind") == "dispatch")
            ]
            if not shown:
                self.main_lay.addWidget(self._empty(bool(scheds)), 0, Qt.AlignmentFlag.AlignHCenter)
            groups: List[tuple] = []
