                    if it.get("kind") == "dispatch":
                        card = DispatchCard(it, (lambda i=iid: self.mark_one(i)), (lambda i=iid: self.remove(i)))
                    elif it.get("kind") == "helpers":
                        card = HelpersCard(it, (lambda i=iid: self.mark_one(i)), (lambda i=iid: self.remove(i)))
                    else:
