            if w is not None:
                w.deleteLater()
        self.sched_cards = []
        self.rail_spinner.setVisible(scheds is None)
        self.rail_head.count.setVisible(bool(scheds))
        self.rail_head.count.set_count(len(scheds or []))
        for s in scheds or []:
