    panel = TerminalPanel("dev", sys.argv[2] if len(sys.argv) > 2 else ".")
    panel.setObjectName("panel")
    panel.setAttribute(Qt.WidgetAttribute.WA_StyledBackground, True)
    panel.resize(760, 520)
    panel.show()
    sys.exit(app.exec())
