        g = QRadialGradient(QPointF(cx, cy), 120)
        glow = QColor(t.accent)
        for stop, a in ((0.0, 0.22), (0.3, 0.14), (0.6, 0.05), (1.0, 0.0)):
            glow.setAlphaF(a)
