    events,
    scan,
    list,
    get,
    save,
    remove,
    plan,
    start,
    continue: continueJob,
    pause,
    resume,
    stop,
    retry,
    skip,
    allow,
    review,
    finish,
    exportMarkdown,
    inboxItem,
    playbooks,
    savePlaybook,
    removePlaybook,
    startFromPlaybook,
    pump,
    flush,
    summary,
    begin,
    end,
    _data: data,
