}

export function resize(id, cols, rows) {
  const t = all.get(id);
  if (!t || t.exited || !t.resizable) return;
  if (t.cols === cols && t.rows === rows) return;
  [t.cols, t.rows] = [cols, rows];
  t.io.resize(cols, rows);
}

/** End a terminal; settles when its process is gone (at once where the kill cannot be watched). */
export async function close(id) {
  const t = all.get(id);
  if (!t) return;
  all.delete(id);
  if (t.exited) return;
  try {
    await t.io.kill();
  } catch {
    /* already gone */
  }
}

export function list() {
  return [...all.values()].map((t) => ({ id: t.id, cwd: t.cwd, title: t.title, exited: t.exited, resizable: t.resizable }));
}

export function snapshot(id) {
  const t = all.get(id);
  return t ? { id, buffer: t.chunks.join('').slice(-SCROLLBACK), exited: t.exited, cwd: t.cwd, resizable: t.resizable } : null;
}

export function closeAll() {
  return Promise.all([...all.keys()].map(close));
}
