  const two = dual && numbers && mode === 'unified';
  const limit = maxRows && !expanded ? maxRows : rows.length;
  const shown = rows.slice(0, limit);
  const keyOf = (l: DiffLine) => (l.t === '-' ? `old:${l.o}` : `new:${l.n}`);
