          {rules.length > 0 && <div className="dp-rules faint">Allowed for every repository: {rules.map((r) => r.label || r.key).join('; ')}</div>}
        </div>
        {rep && (rep.prose || rep.proseState === 'writing' || rep.proseState === 'failed') && (
          <div className="dp-box">
