  // be listed leaves the browser as it was; the path field still works.
  const list = useEvent(() => call<Browse>('fs.browse', { dir: browse?.dir || cwd || info?.home }, { quiet: true }).then(setBrowse, () => {}));
  useEffect(() => {
    if (showBrowser) list();
  }, [showBrowser, list]);

