        <textarea aria-label="First message" className="textarea ns-prompt" rows={2} value={prompt} onChange={(e) => setPrompt(e.target.value)} placeholder={`What should Claude do in ${basename(cwd) || 'this folder'}? (optional)`} />
      </section>
    </Dialog>
  );
}

