export function dispatchNeeds(jobs: Record<string, DispatchJob>): number {
  let n = 0;
  for (const j of Object.values(jobs)) if (j.state === 'running' || j.state === 'reviewing') n += (j.needsAction || 0) + (j.canaryWaiting ? 1 : 0);
