      console.error('transcript push failed', e, m);
    }
  }

  private onStream(m: RawMsg) {
    if (m.uuid) {
      if (this.seen.has(m.uuid)) return;
      this.seen.add(m.uuid);
    }
    const e = m.event;
    const parent: string | null = m.parent_tool_use_id || null;
    if (!e) return;
    if (e.type === 'message_start') {
