.radio-row:hover .radio-ico,
.radio-row:hover .radio-hint,
.radio-row.on .radio-ico,
.radio-row.on .radio-hint {
  color: var(--text);
}
.radio-row.danger .radio-label,
.radio-row.danger .radio-ico {
  color: var(--err);
}
.radio-label {
  font-weight: 550;
  white-space: nowrap;
}
.radio-hint {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--fs-small);
  color: var(--text-3);
}
.radio-check {
  color: var(--text);
  display: grid;
  place-items: center;
}

/* segmented control */
.seg {
  display: inline-flex;
  padding: var(--sp-0_5);
  border-radius: var(--r-3);
  background: var(--fill-1);
  box-shadow: inset 0 0 0 1px var(--hair);
}
.seg button {
  display: inline-flex;
  align-items: center;
  gap: var(--sp-1);
  height: 24px;
  padding: 0 var(--sp-2_5);
  border-radius: var(--r-2);
  font-size: var(--fs-small);
  font-weight: 500;
  color: var(--text-2);
}
.seg button:hover:not(:disabled) {
  color: var(--text);
}
.seg button.on {
  background: transparent;
  color: var(--text);
  box-shadow: none;
}
.seg button:disabled {
  opacity: 0.35;
  cursor: default;
}
.seg.sm button {
  height: 22px;
  padding: 0 var(--sp-1_75);
}

