.palette {
  overflow: hidden;
}
.palette .dialog-body {
  padding: 0;
  gap: 0;
}
.pal-input {
  display: flex;
  align-items: center;
  gap: var(--sp-3);
  height: 54px;
  padding: 0 var(--sp-4_5);
  color: var(--text-3);
  box-shadow: 0 1px 0 var(--hair);
}
.pal-input input {
