  align-items: center;
  gap: var(--sp-2);
  font-size: var(--fs-small);
}

/* ---- the finished rows: the overview row without its mark column */
.dp-fin {
  width: 100%;
  cursor: pointer;
  grid-template-columns: minmax(0, 1fr) auto;
}

/* ---- the job view */
.status-pill.review,
.status-pill.paused {
  color: var(--text-3);
}
.dp-top {
  display: grid;
  gap: var(--sp-2);
  padding: var(--sp-1_5) var(--sp-5) var(--sp-2);
}
.dp-box {
  display: grid;
  gap: var(--sp-1);
  padding: var(--sp-2_25) var(--sp-3);
  border-radius: var(--r-4);
  background: var(--card);
  box-shadow: inset 0 0 0 0.5px var(--hair);
}
.dp-box-h {
  display: flex;
  align-items: baseline;
  gap: var(--sp-2_5);
  font-size: var(--fs-micro);
  font-weight: 600;
