}
.changes-files {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 0 0 var(--sp-6);
  display: grid;
  align-content: start;
}
/* Files read as one continuous document: sticky headers, hairlines between files, no boxes. */
.cfile {
  min-width: 0;
  box-shadow: inset 0 -1px 0 var(--hair);
}
.cfile-head {
  position: sticky;
  top: 0;
  z-index: 2;
  display: flex;
  align-items: center;
  gap: var(--sp-1_5);
  min-height: 40px;
  padding: 0 var(--sp-2) 0 var(--sp-1_5);
  background: var(--chrome);
  font-size: var(--fs-small);
}
.cfile.open .cfile-head {
  box-shadow: inset 0 -1px 0 var(--hair);
}
.cfile-head .icon-btn {
  opacity: 0;
}
.cfile-head:hover .icon-btn,
.cfile-head .icon-btn:focus-visible {
  opacity: 1;
}
.cfile-toggle {
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: var(--sp-1_75);
  height: 30px;
  padding: 0 var(--sp-1);
  text-align: left;
  border-radius: var(--r-2);
}
.cfile-toggle > svg {
  flex: none;
