/* ================================================================ session
   The session on screen around the conversation: its header and crumbs, the folder picker, the
   fresh-session state, MCP notices, the find bar, and the narrow-window container queries. */

/* ================================================================ session */

.session {
  position: relative;
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
}

.session-head {
  position: relative;
  container-type: inline-size;
  z-index: 2;
  flex: none;
  display: flex;
  align-items: center;
  gap: var(--sp-3);
  height: var(--header-h);
  padding: 0 var(--sp-2_5) 0 var(--sp-5);
  background: color-mix(in srgb, var(--canvas) 74%, transparent);
  -webkit-backdrop-filter: blur(22px) saturate(160%);
  backdrop-filter: blur(22px) saturate(160%);
}
.session-head.scrolled {
  box-shadow: 0 1px 0 var(--hair);
}
.session-title-wrap {
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: center;
  gap: var(--sp-2_5);
}
.session-title {
  margin: 0;
  min-width: 0;
  flex: 0 1 auto;
  font-size: var(--fs-ui-plus);
  font-weight: 600;
  letter-spacing: -0.006em;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  cursor: default;
}
.title-input {
  height: 28px;
  max-width: 420px;
  font-weight: 600;
}
.session-crumbs {
  display: flex;
  align-items: center;
  gap: var(--sp-2_5);
  min-width: 0;
  flex: 0 10 auto;
  color: var(--text-3);
  font-size: var(--fs-small);
  white-space: nowrap;
  overflow: hidden;
}
.crumb {
  display: inline-flex;
  align-items: center;
  gap: var(--sp-1);
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}
.crumb svg {
  opacity: 0.8;
}
.crumb.wt {
  color: var(--plan);
}

.status-pill {
  display: inline-flex;
  align-items: center;
  gap: var(--sp-1_75);
  flex: none;
  height: 22px;
  padding: 0 var(--sp-1);
  font-size: var(--fs-small);
  font-weight: 500;
  color: var(--text-3);
}
.status-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: currentColor;
}

.status-pill.requires_action {
  color: var(--accent-text);
  font-weight: 550;
}
.status-pill.error {
  color: var(--err);
}

.session-actions {
  display: flex;
