  .cbtn.mode .cbtn-chev {
    display: none;
  }
}
@container (max-width: 560px) {
  .session-crumbs {
    display: none;
  }
}

/* ================================================================ find in conversation */

.findbar {
  position: absolute;
  top: calc(var(--header-h) + 10px);
  right: 18px;
  z-index: var(--z-float);
  display: flex;
  align-items: center;
  gap: var(--sp-0_5);
  width: min(380px, calc(100% - 36px));
  height: 38px;
  padding: 0 var(--sp-1_25) 0 var(--sp-2_75);
