  cursor: pointer;
}
.crumb-btn:hover,
.crumb-btn.on {
  background: var(--fill-2);
  color: var(--text);
}
.crumb-chev {
  opacity: 0.7;
  margin-left: 1px;
}

/* folder picker (popover) */
.fpick {
  display: flex;
  flex-direction: column;
  min-height: 0;
  max-height: min(60vh, 460px);
}
.fpick-search {
  display: flex;
  align-items: center;
  gap: var(--sp-2);
  height: 36px;
  padding: 0 var(--sp-2_5) 0 var(--sp-3);
  border-bottom: 1px solid var(--hair);
  color: var(--text-3);
  cursor: text;
}
.fpick-search input {
  flex: 1;
  min-width: 0;
  background: none;
  border: 0;
  outline: 0;
  color: var(--text);
  font-size: var(--fs-ui);
}
.fpick-search input::placeholder {
  color: var(--text-3);
}
.fpick-list {
  padding: var(--sp-1_5);
  overflow-y: auto;
}
.fpick-row {
  display: grid;
  grid-template-columns: 16px minmax(0, 1fr) auto;
  align-items: center;
  gap: var(--sp-2_5);
